mapper.select:
SELECT r.id AS id, r.task_id AS taskId, r.violation_type AS violationType, r.handle_method AS handleMethod, r.handle_type AS handleType, r.status AS status, r.area_id AS areaId, a.name AS areaName, r.handle_user_id AS handleUserId, u.nickname AS handleUserName, r.handle_time AS handleTime, r.rectify_status AS rectifyStatus, r.reject_reason AS rejectReason, r.remark AS remark, r.reserve1 AS reserve1, r.reserve2 AS reserve2, r.creator AS creator, r.updater AS updater, r.create_time AS createTime, r.update_time AS updateTime FROM result_handle r LEFT JOIN area_info a ON r.area_id = a.id AND a.deleted = 0 LEFT JOIN user_info u ON r.handle_user_id = u.id AND u.deleted = 0 WHERE r.deleted = 0
AND r.task_id = #{reqVO.taskId}
AND r.violation_type = #{reqVO.violationType}
AND r.handle_method = #{reqVO.handleMethod}
AND r.status = #{reqVO.status}
AND r.area_id = #{reqVO.areaId}
AND r.handle_user_id = #{reqVO.handleUserId}
AND r.handle_time BETWEEN FROM_UNIXTIME(#{reqVO.handleTimeNew[0]}) AND FROM_UNIXTIME(#{reqVO.handleTimeNew[1]})
AND r.rectify_status = #{reqVO.rectifyStatus}
AND r.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY r.id DESC
